#include <iostream>
#include <map>
#include <functional>
using namespace std;

enum class TrafficState { GREEN, YELLOW, RED };
enum class TrafficEvent { TIMER, EMERGENCY };

class TrafficLight {
    TrafficState state = TrafficState::GREEN;
public:
    void handle(TrafficEvent e) {
        switch(state) {
            case TrafficState::GREEN:
                if (e == TrafficEvent::TIMER) { state = TrafficState::YELLOW; cout << "GREEN -> YELLOW\n"; }
                break;
            case TrafficState::YELLOW:
                if (e == TrafficEvent::TIMER) { state = TrafficState::RED; cout << "YELLOW -> RED\n"; }
                break;
            case TrafficState::RED:
                if (e == TrafficEvent::TIMER) { state = TrafficState::GREEN; cout << "RED -> GREEN\n"; }
                break;
        }
    }
    TrafficState getState() const { return state; }
};

int main() {
    TrafficLight tl;
    tl.handle(TrafficEvent::TIMER);
    tl.handle(TrafficEvent::TIMER);
    tl.handle(TrafficEvent::TIMER);
    tl.handle(TrafficEvent::TIMER);
    return 0;
}
